const I18n=(()=>{
 const languages=[['uz','O‘zbekcha'],['en','English'],['ru','Русский'],['tr','Türkçe'],['kk','Қазақша'],['ar','العربية'],['zh-CN','中文'],['hi','हिन्दी'],['es','Español'],['fr','Français']];
 let saved;try{saved=localStorage.getItem('tona_language')}catch{}
 const browser=(navigator.language||'uz').split('-')[0];
 const language=languages.some(x=>x[0]===saved)?saved:(browser==='zh'?'zh-CN':languages.some(x=>x[0]===browser)?browser:'en');
 const locale={uz:'uz-UZ',en:'en-US',ru:'ru-RU',tr:'tr-TR',kk:'kk-KZ',ar:'ar', 'zh-CN':'zh-CN',hi:'hi-IN',es:'es-ES',fr:'fr-FR'}[language];
 const t=key=>language==='uz'?(TONA_TRANSLATIONS.uz?.[key]??key):(TONA_TRANSLATIONS[language]?.[key]??TONA_TRANSLATIONS.en?.[key]??key);
 const escape=value=>String(value).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 document.documentElement.lang=language;document.documentElement.dir=language==='ar'?'rtl':'ltr';
 function picker(){return `<label class="language-picker"><span aria-hidden="true">◎</span><span class="sr-only">${escape(t('Interfeys tili'))}</span><select data-language aria-label="${escape(t('Interfeys tili'))}">${languages.map(([code,label])=>`<option value="${code}" lang="${code}" ${code===language?'selected':''}>${escape(label)}</option>`).join('')}</select></label>`}
 function choose(code){if(!languages.some(x=>x[0]===code))return;try{localStorage.setItem('tona_language',code)}catch{return}location.reload()}
 return {language,locale,t,picker,choose,languages};
})();
